{
  "name": "opencode-supermemory-gdrive",
  "version": "2.0.17",
  "description": "OpenCode plugin with persistent memory backed by Google Drive",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/rpc.d.ts",
      "import": "./dist/rpc.js",
      "default": "./dist/rpc.js"
    },
    "./v2": {
      "types": "./dist/v2/index.d.ts",
      "import": "./dist/v2/index.js",
      "default": "./dist/v2/index.js"
    },
    "./package.json": "./package.json"
  },
  "bin": {
    "opencode-supermemory-gdrive": "./dist/cli.js"
  },
  "scripts": {
    "generate:version": "node scripts/sync-version.mjs",
    "build": "node scripts/sync-version.mjs && bun build ./src/index.ts ./src/server.ts ./src/backend.ts ./src/rpc.ts --outdir ./dist --target node --external @opencode-ai/plugin --external zod && bun build ./src/tui.tsx --outfile ./dist/tui.js --target bun --external @opentui/core --external @opentui/solid --external solid-js && bun build ./src/v2/index.ts --outfile ./dist/v2/index.js --target node --external @opencode-ai/plugin --external zod && bun build ./src/cli.ts --outfile ./dist/cli.js --target node && node scripts/copy-sdk-licenses.mjs",
    "dev": "tsc --watch",
    "typecheck": "node scripts/sync-version.mjs && tsc --noEmit",
    "test": "node scripts/sync-version.mjs && bun test"
  },
  "keywords": [
    "ai",
    "coding-agent",
    "memory",
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "plugin",
    "supermemory"
  ],
  "author": "Supermemory",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/supermemoryai/opencode-supermemory"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.20",
    "@opencode/plugin": "2.0.15",
    "@opentui/core": "0.5.10",
    "@opentui/solid": "0.5.10",
    "@types/bun": "latest",
    "jsonc-parser": "3.3.1",
    "solid-js": "1.9.15",
    "supermemory": "5.0.1",
    "supermemory-legacy": "npm:supermemory@4.0.0",
    "typescript": "^5.7.3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "permission.ask",
      "event"
    ]
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@hono/node-server": "^2.1.5",
    "hono": "^4.13.14",
    "zod": "4.1.8"
  }
}
